import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import MarketDashboard from './components/MarketDashboard';
import { Plus, LayoutGrid, Clock, Hash, Calendar, Sparkles } from 'lucide-react';
import { generateMarketSummary } from './services/geminiService';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiSummary, setAiSummary] = useState('');

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    if (activeCategory === '全部') return insights;
    return insights.filter(i => i.category === activeCategory);
  }, [insights, activeCategory]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: Date.now(),
        completionStatus: '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条策略记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleGenerateAI = async () => {
    setIsGeneratingAI(true);
    const summary = await generateMarketSummary(insights);
    setAiSummary(summary || "分析完成。");
    setIsGeneratingAI(false);
  };

  return (
    <div className="min-h-screen flex flex-col relative">
      <header className="px-8 pt-12 pb-6 max-w-[1400px] mx-auto w-full">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 border-b border-gray-200/60 pb-8">
          <div>
            <h1 className="font-serif-title text-[48px] font-black text-[#1a1a1a] tracking-tight mb-2">
              资产策略
            </h1>
            <div className="w-32 h-[3px] bg-gray-900 rounded-full"></div>
          </div>

          <div className="flex items-center gap-6">
            <nav className="flex gap-8">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`text-[15px] font-bold transition-all relative py-2 ${
                    activeCategory === cat ? 'text-gray-900' : 'text-gray-400 hover:text-gray-600'
                  }`}
                >
                  {cat}
                  {activeCategory === cat && <span className="absolute bottom-0 left-0 w-full h-0.5 bg-gray-900"></span>}
                </button>
              ))}
            </nav>
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-gray-900 text-white w-10 h-10 rounded-full hover:bg-black transition-all flex items-center justify-center shadow-lg active:scale-95"
            >
              <Plus className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-[1400px] mx-auto px-8 py-12 w-full flex-grow">
        <MarketDashboard 
          insights={insights} 
          onGenerateAI={handleGenerateAI} 
          isGeneratingAI={isGeneratingAI} 
          aiSummary={aiSummary} 
        />

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
          {filteredInsights.map(insight => (
            <MarketCard 
              key={insight.id} 
              insight={insight} 
              onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
              onDelete={handleDeleteInsight}
            />
          ))}

          {/* 添加按钮占位卡片 */}
          <button 
            onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
            className="border-2 border-dashed border-gray-200 rounded-3xl flex flex-col items-center justify-center gap-4 text-gray-300 hover:border-gray-400 hover:text-gray-400 transition-all min-h-[480px] bg-white/30"
          >
            <Plus className="w-12 h-12 stroke-[1px]" />
            <span className="font-bold text-sm tracking-widest">添加新资产策略</span>
          </button>
        </div>
      </main>

      <footer className="py-20 text-center opacity-30">
        <p className="text-[12px] font-bold uppercase tracking-[0.5em] text-gray-900 italic">
          — Trading Journal Strategy Insight —
        </p>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

