    case '看跌': return { color: 'text-rose-600', bg: 'bg-rose-50', icon: <TrendingDown className="w-4 h-4" /> };
    default: return { color: 'text-blue-600', bg: 'bg-blue-50', icon: <Minus className="w-4 h-4" /> };
  }
};

