  const statusStyle = getStatusStyles(insight.status);
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' });

  return (
    <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-6 border border-gray-100 shadow-sm hover:shadow-md transition-all group relative">
      <div className="flex justify-between items-start mb-4">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <h3 className="text-xl font-bold text-gray-900 tracking-tight">{insight.symbol}</h3>
            <span className={`text-[10px] px-2 py-0.5 rounded-md font-bold uppercase tracking-wider ${statusStyle.bg} ${statusStyle.color}`}>
              {insight.category}
            </span>
          </div>
          <div className="flex items-center gap-1.5 text-gray-400 text-xs font-medium">
            <Calendar className="w-3 h-3" />
            {date}
          </div>
        </div>

        <div className={`flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold ${statusStyle.bg} ${statusStyle.color}`}>
          {statusStyle.icon}
          {insight.status}
        </div>
      </div>

      <div className="space-y-4">
        <div>
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1.5">核心观察</p>
          <p className="text-sm text-gray-600 leading-relaxed line-clamp-3">
            {insight.focusPoints}
